import { useState } from 'react';
import { SegmentedControl, Stack } from '@mantine/core';
import { CheckoutForm } from './CheckoutForm';
import { NewsletterForm } from './NewsletterForm';
import { SignupForm } from './SignupForm';

const FORMS = [
  { value: 'signup', label: 'Sign up' },
  { value: 'checkout', label: 'Checkout' },
  { value: 'newsletter', label: 'Newsletter' },
];

export function ReusableFieldsAcrossForms() {
  const [activeForm, setActiveForm] = useState('signup');

  return (
    <Stack maw={420} mx="auto">
      <SegmentedControl size="md" data={FORMS} value={activeForm} onChange={setActiveForm} />

      {activeForm === 'signup' && <SignupForm />}
      {activeForm === 'checkout' && <CheckoutForm />}
      {activeForm === 'newsletter' && <NewsletterForm />}
    </Stack>
  );
}

import { Button, Fieldset, Group, Stack, TextInput } from '@mantine/core';
import { FormErrors, isNotEmpty, useForm } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { EmailField, emailRule } from './EmailField';

interface CheckoutValues {
  contact: {
    fullName: string;
    email: string;
  };
  invoice: {
    company: string;
    email: string;
  };
}

export function CheckoutForm() {
  const form = useForm<CheckoutValues>({
    initialValues: {
      contact: {
        fullName: '',
        email: '',
      },
      invoice: {
        company: '',
        email: '',
      },
    },
    validate: {
      contact: {
        fullName: isNotEmpty('Full name is required'),
        email: emailRule,
      },
      invoice: {
        email: (value) => (value ? emailRule(value) : null),
      },
    },
  });

  const handleSubmit = (values: CheckoutValues) => {
    const invoiceEmail = values.invoice.email || values.contact.email;

    notifications.show({
      title: 'Order placed',
      message: `Order confirmation goes to ${values.contact.email}, invoice to ${invoiceEmail}`,
    });
  };

  const handleErrors = (errors: FormErrors) => {
    form.getInputNode(Object.keys(errors)[0])?.focus();
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit, handleErrors)}>
      <Stack>
        <Fieldset legend="Contact">
          <Stack gap="sm">
            <TextInput
              size="md"
              label="Full name"
              placeholder="Jane Doe"
              withAsterisk
              {...form.getInputProps('contact.fullName')}
            />

            <EmailField field={form.getField('contact.email')} withAsterisk />
          </Stack>
        </Fieldset>

        <Fieldset legend="Invoice">
          <Stack gap="sm">
            <TextInput
              size="md"
              label="Company"
              placeholder="Mantine Inc."
              {...form.getInputProps('invoice.company')}
            />

            <EmailField
              field={form.getField('invoice.email')}
              label="Invoice email"
              placeholder="billing@mantine.dev"
              description="Leave empty to send the invoice to the contact email"
            />
          </Stack>
        </Fieldset>

        <Group justify="flex-end">
          <Button size="md" type="submit">
            Place order
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { TextInput, TextInputProps } from '@mantine/core';
import { isEmail, UseFieldReturnType } from '@mantine/form';

export const emailRule = isEmail('Enter a valid email address');

interface EmailFieldProps extends Omit<TextInputProps, 'value' | 'onChange' | 'error'> {
  field: UseFieldReturnType<string>;
}

export function EmailField({ field, label = 'Email', ...others }: EmailFieldProps) {
  const inputProps = field.getInputProps();

  const handleBlur = () => {
    inputProps.onBlur?.();
    const normalized = field.getValue().trim().toLowerCase();

    if (normalized !== field.getValue()) {
      field.setValue(normalized);
    }
  };

  return (
    <TextInput
      size="md"
      inputMode="email"
      label={label}
      placeholder="you@mantine.dev"
      autoComplete="email"
      {...others}
      {...inputProps}
      onBlur={handleBlur}
    />
  );
}

import { Button, Group, Stack } from '@mantine/core';
import { useField } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { EmailField, emailRule } from './EmailField';

export function NewsletterForm() {
  const email = useField({
    initialValue: '',
    validate: emailRule,
  });

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const error = await email.validate();

    if (!error) {
      notifications.show({
        title: 'Subscribed',
        message: `Weekly updates will be sent to ${email.getValue()}`,
      });
      email.reset();
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Stack>
        <EmailField field={email} description="One email per week, unsubscribe at any time" />

        <Group justify="flex-end">
          <Button size="md" type="submit">
            Subscribe
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { Button, Group, PasswordInput, Stack, TextInput } from '@mantine/core';
import { FormErrors, hasLength, isNotEmpty, useForm } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { EmailField, emailRule } from './EmailField';

interface SignupValues {
  fullName: string;
  email: string;
  password: string;
}

export function SignupForm() {
  const form = useForm<SignupValues>({
    initialValues: {
      fullName: '',
      email: '',
      password: '',
    },
    validate: {
      fullName: isNotEmpty('Full name is required'),
      email: emailRule,
      password: hasLength({ min: 8 }, 'Password must be at least 8 characters'),
    },
  });

  const handleSubmit = (values: SignupValues) => {
    notifications.show({
      title: 'Account created',
      message: `Welcome, ${values.fullName}. We sent a confirmation link to ${values.email}`,
    });
  };

  const handleErrors = (errors: FormErrors) => {
    form.getInputNode(Object.keys(errors)[0])?.focus();
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit, handleErrors)}>
      <Stack>
        <TextInput
          size="md"
          label="Full name"
          placeholder="Jane Doe"
          withAsterisk
          {...form.getInputProps('fullName')}
        />

        <EmailField field={form.getField('email')} withAsterisk />

        <PasswordInput
          size="md"
          label="Password"
          placeholder="At least 8 characters"
          withAsterisk
          {...form.getInputProps('password')}
        />

        <Group justify="flex-end">
          <Button size="md" type="submit">
            Create account
          </Button>
        </Group>
      </Stack>
    </form>
  );
}
